async def _run_skill_deferred_calls(turn_id):
    # [I] run activator.run_deferred for calls queued this turn.
    #     [S] "skill deferred call: turn=" / "...done:" / "...failed:".
    for call in _pending_skill_deferred_calls(turn_id):
        try:
            log.info(f"skill deferred call: turn={turn_id}")  # [S]
            await get_skill_activator().run_deferred(call["skill_name"], **call.get("args", {}))
            log.info(f"skill deferred call done: turn={turn_id}")  # [S]
        except Exception as e:
            log.warning(f"skill deferred call failed: turn={turn_id}: {e}")  # [S]


